    // ============================================================
    // Platform
    // ============================================================

    function detectRuntimePlatform() {
        const ua = navigator.userAgent || '';
        const vendor = navigator.vendor || '';
        const host = location.hostname.toLowerCase();
        const isIOS = /iPad|iPhone|iPod/.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
        const isAndroid = /Android/.test(ua);
        const isSafari = /Safari\//.test(ua) &&
            !/Chrome|Chromium|CriOS|Edg|OPR|Firefox|FxiOS/.test(ua) &&
            /Apple/i.test(vendor || ua);
        const hasGMStorage = typeof GM_getValue === 'function' &&
            typeof GM_setValue === 'function' &&
            typeof GM_deleteValue === 'function';
        const hasGMNetwork = typeof GM_xmlhttpRequest === 'function';
        const siteFamily = host.endsWith('.vk.me') ? 'vk.me' : 'vk';

        return {
            ua,
            host,
            siteFamily,
            isIOS,
            isAndroid,
            isSafari,
            hasGMStorage,
            hasGMNetwork,
        };
    }

    function getPlatformDisplayName() {
        if (RUNTIME_PLATFORM.isSafari && RUNTIME_PLATFORM.isIOS) return 'Safari на iPhone/iPad';
        if (RUNTIME_PLATFORM.isSafari) return 'Safari';
        if (RUNTIME_PLATFORM.isAndroid) return 'Android';
        if (RUNTIME_PLATFORM.siteFamily === 'vk.me') return 'VK Me';
        return 'эта платформа';
    }

    function getCrossOriginMediaBlockReason(url) {
        if (!/^https?:/i.test(url || '')) return '';
        if (String(url).startsWith(location.origin)) return '';
        if (RUNTIME_PLATFORM.hasGMNetwork) return '';

        if (RUNTIME_PLATFORM.isSafari) {
            return `${getPlatformDisplayName()} не даёт расшифровать вложения на этом сайте`;
        }

        return 'Эта платформа не даёт расшифровать вложения на этом сайте';
    }

    function applyMediaPlatformBlock(box, reason) {
        if (!box) return;

        const meta = box.querySelector('.vk-p2p-media-meta');
        const error = box.querySelector('.vk-p2p-media-error');
        const decryptBtn = box.querySelector('.vk-p2p-media-btn');
        const downloadLink = box.querySelector('.vk-p2p-media-download');

        if (meta) {
            meta.textContent = reason;
        }
        if (error) {
            error.textContent = '';
        }
        if (downloadLink) {
            downloadLink.hidden = true;
            downloadLink.removeAttribute('href');
            downloadLink.removeAttribute('download');
        }
        if (decryptBtn) {
            decryptBtn.hidden = true;
            decryptBtn.disabled = false;
            decryptBtn.title = reason;
            decryptBtn.textContent = '🔓 Расшифровать вложение';
        }

        box.dataset.vkP2PPlatformBlocked = 'true';
    }

    // ============================================================
    // Storage
    // ============================================================

    function safeJsonParse(value, fallback) {
        try {
            if (!value) return fallback;
            return JSON.parse(value);
        } catch {
            return fallback;
        }
    }

    function canUseLocalStorage() {
        try {
            const probeKey = `${STORAGE_FALLBACK_PREFIX}probe`;
            localStorage.setItem(probeKey, '1');
            localStorage.removeItem(probeKey);
            return true;
        } catch {
            return false;
        }
    }

    function gmGetValueCompat(key, fallback) {
        if (typeof GM_getValue === 'function') {
            return GM_getValue(key, fallback);
        }

        if (!canUseLocalStorage()) {
            return fallback;
        }

        const value = localStorage.getItem(`${STORAGE_FALLBACK_PREFIX}${key}`);
        return value === null ? fallback : value;
    }

    function gmSetValueCompat(key, value) {
        if (typeof GM_setValue === 'function') {
            GM_setValue(key, value);
            return;
        }

        if (!canUseLocalStorage()) {
            return;
        }

        localStorage.setItem(`${STORAGE_FALLBACK_PREFIX}${key}`, value);
    }

    function gmDeleteValueCompat(key) {
        if (typeof GM_deleteValue === 'function') {
            GM_deleteValue(key);
            return;
        }

        if (!canUseLocalStorage()) {
            return;
        }

        localStorage.removeItem(`${STORAGE_FALLBACK_PREFIX}${key}`);
    }

    function gmGetJson(key, fallback) {
        return safeJsonParse(gmGetValueCompat(key, null), fallback);
    }

    function gmSetJson(key, value) {
        gmSetValueCompat(key, JSON.stringify(value));
    }

    function loadSettings() {
        const saved = gmGetJson(STORAGE_KEYS.SETTINGS, null);
        if (saved && typeof saved === 'object') {
            const normalized = { ...saved };

            if (typeof normalized.autoDecrypt !== 'boolean' && typeof normalized.decryptIncoming === 'boolean') {
                normalized.autoDecrypt = normalized.decryptIncoming;
            }

            if (!Object.prototype.hasOwnProperty.call(normalized, 'cipherCodec')) {
                normalized.cipherCodec = normalized.emojiCipher ? 'emoji' : 'base64';
            }

            settings = {
                ...settings,
                ...normalized
            };
        }
    }

    function saveSettings() {
        gmSetJson(STORAGE_KEYS.SETTINGS, {
            ...settings,
            decryptIncoming: settings.autoDecrypt,
            emojiCipher: settings.cipherCodec === 'emoji'
        });
    }

    function isValidKeyHex(hex) {
        return typeof hex === 'string' && /^[0-9a-f]{64}$/i.test(hex);
    }

    function areValidDerivedKeys(keys) {
        return Boolean(
            keys &&
            isValidKeyHex(keys.k1) &&
            isValidKeyHex(keys.k2) &&
            isValidKeyHex(keys.k3) &&
            isValidKeyHex(keys.k4)
        );
    }

    function normalizeKeyObject(obj) {
        const out = {};
        for (const [k, v] of Object.entries(obj || {})) {
            if (isValidKeyHex(v)) out[k] = String(v).toLowerCase();
        }
        return out;
    }

    function normalizeCustomKeyEntry(raw) {
        if (!raw) return null;

        if (typeof raw === 'string') {
            if (!isValidKeyHex(raw)) return null;
            return { key: raw.toLowerCase(), label: '' };
        }

        if (typeof raw === 'object') {
            if (!isValidKeyHex(raw.key)) return null;
            const label = typeof raw.label === 'string'
                ? raw.label.trim().slice(0, 64)
                : '';
            return { key: String(raw.key).toLowerCase(), label };
        }

        return null;
    }

    function loadDerivedKeys() {
        const saved = gmGetJson(STORAGE_KEYS.DERIVED_KEYS, null);
        if (areValidDerivedKeys(saved)) return normalizeKeyObject(saved);
        return null;
    }

    function saveDerivedKeys(keys) {
        if (!areValidDerivedKeys(keys)) return;
        gmSetJson(STORAGE_KEYS.DERIVED_KEYS, normalizeKeyObject(keys));
    }

    function clearDerivedKeys() {
        gmDeleteValueCompat(STORAGE_KEYS.DERIVED_KEYS);
        DERIVED_KEYS = null;
    }

    function loadCustomKeys() {
        const saved = gmGetJson(STORAGE_KEYS.CUSTOM_KEYS, {});
        const out = {};
        for (const [slot, raw] of Object.entries(saved || {})) {
            const normalized = normalizeCustomKeyEntry(raw);
            if (normalized) out[slot] = normalized;
        }
        CUSTOM_KEYS = out;
    }

    function saveCustomKeys() {
        gmSetJson(STORAGE_KEYS.CUSTOM_KEYS, CUSTOM_KEYS);
    }

    function resetAllKeys() {
        clearDerivedKeys();
        gmDeleteValueCompat(STORAGE_KEYS.CUSTOM_KEYS);
        clearChatKeySlots();
        CUSTOM_KEYS = {};
        TEMP_KEY = null;
        currentKeySlot = DEFAULT_KEY_SLOT;
        updateEncryptButtonsTitle();
        showSeedSetupModal();
    }
    // ============================================================
    // Per-chat key selection
    // ============================================================

    function normalizeChatKeySlots(value) {
        const normalized = {};

        for (const [chatId, slotId] of Object.entries(value || {})) {
            if (!/^vk:(peer|chat):[^\s]{1,96}$/.test(chatId)) continue;
            if (typeof slotId !== 'string' || !slotId || slotId.length > 64) continue;
            normalized[chatId] = slotId;
        }

        return normalized;
    }

    function loadChatKeySlots() {
        CHAT_KEY_SLOTS = normalizeChatKeySlots(
            gmGetJson(STORAGE_KEYS.CHAT_KEY_SLOTS, {})
        );
    }

    function saveChatKeySlots() {
        gmSetJson(STORAGE_KEYS.CHAT_KEY_SLOTS, CHAT_KEY_SLOTS);
    }

    function normalizeChatPeerId(rawValue) {
        let value;
        try {
            value = decodeURIComponent(String(rawValue || ''));
        } catch {
            return '';
        }

        value = value.trim().replace(/^peer:/i, '');
        if (!value || value.length > 96) return '';

        if (/^c\d+$/i.test(value)) {
            return `vk:chat:${value.toLowerCase()}`;
        }
        if (/^-?\d+$/.test(value)) {
            return `vk:peer:${value}`;
        }
        if (/^[a-z0-9_.-]+$/i.test(value)) {
            return `vk:peer:${value.toLowerCase()}`;
        }

        return '';
    }

    function getCurrentChatId(urlValue = location.href) {
        let url;
        try {
            url = new URL(urlValue, location.origin);
        } catch {
            return '';
        }

        const queryPeer = ['sel', 'peer', 'peer_id', 'chat', 'convo']
            .map(name => url.searchParams.get(name))
            .find(Boolean);
        if (queryPeer) return normalizeChatPeerId(queryPeer);

        const pathMatch = /\/(?:mail\/)?convo\/([^/?#]+)/i.exec(url.pathname) ||
            /\/im\/(?:convo\/)?([^/?#]+)/i.exec(url.pathname);
        return pathMatch ? normalizeChatPeerId(pathMatch[1]) : '';
    }

    function getFallbackKeySlot() {
        const allKeys = getAllKeys();
        if (allKeys[DEFAULT_KEY_SLOT]) return DEFAULT_KEY_SLOT;
        return Object.keys(allKeys)[0] || DEFAULT_KEY_SLOT;
    }

    function rememberKeyForCurrentChat(slotId) {
        const chatId = getCurrentChatId();
        if (!chatId) return false;

        CHAT_KEY_SLOTS[chatId] = slotId;
        currentChatContextId = chatId;
        saveChatKeySlots();
        return true;
    }

    function selectKeySlot(slotId, { rememberForChat = true } = {}) {
        if (!getAllKeys()[slotId]) return false;

        currentKeySlot = slotId;
        if (rememberForChat) rememberKeyForCurrentChat(slotId);
        updateEncryptButtonsTitle();
        return true;
    }

    function applyRememberedKeyForCurrentChat({ force = false } = {}) {
        const chatId = getCurrentChatId();
        if (!chatId) return false;
        if (!force && currentChatContextId === chatId) return false;

        currentChatContextId = chatId;
        const allKeys = getAllKeys();
        const rememberedSlot = CHAT_KEY_SLOTS[chatId];
        let nextSlot = rememberedSlot;

        if (!nextSlot || !allKeys[nextSlot]) {
            nextSlot = getFallbackKeySlot();
            if (rememberedSlot) {
                delete CHAT_KEY_SLOTS[chatId];
                saveChatKeySlots();
            }
        }

        if (currentKeySlot === nextSlot) return false;
        currentKeySlot = nextSlot;
        updateEncryptButtonsTitle();
        return true;
    }

    function forgetChatKeySlot(slotId) {
        let changed = false;

        for (const [chatId, savedSlot] of Object.entries(CHAT_KEY_SLOTS)) {
            if (savedSlot !== slotId) continue;
            delete CHAT_KEY_SLOTS[chatId];
            changed = true;
        }

        if (changed) saveChatKeySlots();
    }

    function clearChatKeySlots() {
        CHAT_KEY_SLOTS = {};
        currentChatContextId = '';
        gmDeleteValueCompat(STORAGE_KEYS.CHAT_KEY_SLOTS);
    }

    function initChatKeyNavigation() {
        if (history.pushState?.vkP2PWrapped) return;

        const refresh = () => {
            currentChatContextId = '';
            applyRememberedKeyForCurrentChat({ force: true });
            scheduleScan();
        };

        ['pushState', 'replaceState'].forEach(methodName => {
            const original = history[methodName];
            if (typeof original !== 'function') return;

            const wrapped = function (...args) {
                const result = original.apply(this, args);
                refresh();
                return result;
            };
            wrapped.vkP2PWrapped = true;
            history[methodName] = wrapped;
        });

        window.addEventListener('popstate', refresh);
    }
    // ============================================================
    // Crypto helpers
    // ============================================================

    function hexToBytes(hex) {
        if (!isValidKeyHex(hex)) throw new Error('Invalid key hex');
        const arr = new Uint8Array(hex.length / 2);
        for (let i = 0; i < hex.length; i += 2) {
            arr[i / 2] = parseInt(hex.substr(i, 2), 16);
        }
        return arr;
    }

    function bytesToHex(bytes) {
        return Array.from(bytes)
            .map(b => b.toString(16).padStart(2, '0'))
            .join('');
    }

    function bytesToBase64(bytes) {
        let binary = '';
        const chunkSize = 0x8000;

        for (let i = 0; i < bytes.length; i += chunkSize) {
            const chunk = bytes.subarray(i, i + chunkSize);
            binary += String.fromCharCode.apply(null, chunk);
        }

        return btoa(binary);
    }

    function utf8ToBytes(text) {
        return new TextEncoder().encode(text);
    }

    function bytesToUtf8(bytes) {
        return new TextDecoder().decode(bytes);
    }

    function concatBytes(parts) {
        const total = parts.reduce((sum, part) => sum + part.length, 0);
        const out = new Uint8Array(total);
        let offset = 0;

        parts.forEach(part => {
            out.set(part, offset);
            offset += part.length;
        });

        return out;
    }

    function uint32ToBytes(value) {
        const out = new Uint8Array(4);
        new DataView(out.buffer).setUint32(0, value, false);
        return out;
    }

    function bytesToUint32(bytes, offset = 0) {
        return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).getUint32(offset, false);
    }

    function base64ToBytes(b64) {
        const bin = atob(b64);
        const data = new Uint8Array(bin.length);

        for (let i = 0; i < bin.length; i++) {
            data[i] = bin.charCodeAt(i);
        }

        return data;
    }

    function encodeBase64ToAlphabet(b64, alphabet, padChar = '=') {
        let out = '';

        for (const ch of b64) {
            if (ch === '=') {
                continue;
            }

            const idx = BASE64_ALPHABET.indexOf(ch);
            if (idx === -1) throw new Error('Invalid base64 char: ' + ch);
            out += alphabet[idx];
        }

        return out;
    }

    function decodeAlphabetToBase64(payload, alphabet, padChar = '=') {
        let out = '';

        for (const symbol of Array.from(payload)) {
            if (symbol === padChar) {
                out += '=';
                continue;
            }

            const idx = alphabet.indexOf(symbol);
            if (idx === -1) throw new Error('Invalid cipher symbol: ' + symbol);
            out += BASE64_ALPHABET[idx];
        }

        return out + '='.repeat((4 - (out.length % 4)) % 4);
    }

    function encodeBase64ToEmoji(b64) {
        return encodeBase64ToAlphabet(b64, EMOJI_ALPHABET, EMOJI_PAD);
    }

    function decodeEmojiToBase64(payload) {
        return decodeAlphabetToBase64(payload, EMOJI_ALPHABET, EMOJI_PAD);
    }

    function encodeBase64ToCyrillic(b64) {
        return encodeBase64ToAlphabet(b64, CYRILLIC_ALPHABET);
    }

    function decodeCyrillicToBase64(payload) {
        return decodeAlphabetToBase64(payload, CYRILLIC_ALPHABET);
    }

    function getCipherCodecConfig(codecId) {
        return CIPHER_CODECS[codecId] || CIPHER_CODECS.emoji;
    }

    function normalizeCodecId(codecId) {
        return Object.prototype.hasOwnProperty.call(CIPHER_CODECS, codecId) ? codecId : 'emoji';
    }

    function encodePayloadForCodec(b64, codecId) {
        switch (normalizeCodecId(codecId)) {
            case 'base64':
                return b64.replace(/=+$/u, '');
            case 'cyrillic':
                return encodeBase64ToCyrillic(b64);
            case 'emoji':
            default:
                return encodeBase64ToEmoji(b64);
        }
    }

    function decodePayloadForCodec(payload, codecId) {
        switch (normalizeCodecId(codecId)) {
            case 'base64':
                return payload + '='.repeat((4 - (payload.length % 4)) % 4);
            case 'cyrillic':
                return decodeCyrillicToBase64(payload);
            case 'emoji':
            default:
                return decodeEmojiToBase64(payload);
        }
    }

    function isValidBase64Payload(payload) {
        return typeof payload === 'string'
            && payload.length >= 4
            && payload.length % 4 === 0
            && /^[A-Za-z0-9+/]+={0,2}$/.test(payload);
    }

    function isPlausibleEncodedPayload(payload, codecId) {
        if (typeof payload !== 'string' || !payload) return false;

        try {
            const b64 = decodePayloadForCodec(payload, codecId);
            return isValidBase64Payload(b64);
        } catch {
            return false;
        }
    }

    function toCompactKeyId(slotId) {
        const match = /^k([1-4])$/.exec(slotId);
        return match ? match[1] : slotId;
    }

    function fromCompactKeyId(compactId) {
        return /^[1-4]$/.test(compactId) ? `k${compactId}` : compactId;
    }

    function formatEncryptedMessage(slotId, payload, codecId) {
        const codec = getCipherCodecConfig(codecId);
        return `${FORMAT_START}${toCompactKeyId(slotId)}${FORMAT_MID}${codec.shortCode}${FORMAT_PAYLOAD}${payload}`;
    }

    function parseEncryptedMessage(text) {
        const trimmed = (text || '').trim();
        const compactMatch = new RegExp(`^${FORMAT_START}(.+?)${FORMAT_MID}([${CODEC_MARKERS.base64}${CODEC_MARKERS.emoji}${CODEC_MARKERS.cyrillic}])${FORMAT_PAYLOAD}(.+)$`, 'su').exec(trimmed);
        if (!compactMatch) return null;

        const parsed = {
            originalText: trimmed,
            keyId: fromCompactKeyId(compactMatch[1]),
            codecId: compactMatch[2] === CODEC_MARKERS.emoji
                ? 'emoji'
                : compactMatch[2] === CODEC_MARKERS.cyrillic
                    ? 'cyrillic'
                    : 'base64',
            encodedPayload: compactMatch[3]
        };

        return isPlausibleEncodedPayload(parsed.encodedPayload, parsed.codecId)
            ? parsed
            : null;
    }

    async function deriveKeyMaterialFromSeed(seedText) {
        const encoder = new TextEncoder();

        const baseKey = await crypto.subtle.importKey(
            'raw',
            encoder.encode(seedText),
            'PBKDF2',
            false,
            ['deriveBits']
        );

        const bits = await crypto.subtle.deriveBits(
            {
                name: 'PBKDF2',
                salt: encoder.encode(KDF_SALT),
                iterations: KDF_ITERATIONS,
                hash: 'SHA-256'
            },
            baseKey,
            1024
        );

        const bytes = new Uint8Array(bits);

        return {
            k1: bytesToHex(bytes.slice(0, 32)),
            k2: bytesToHex(bytes.slice(32, 64)),
            k3: bytesToHex(bytes.slice(64, 96)),
            k4: bytesToHex(bytes.slice(96, 128))
        };
    }

    async function deriveKeyFromName(name) {
        if (!name || !name.trim()) {
            throw new Error('Пустое слово');
        }
        const hash = await crypto.subtle.digest(
            'SHA-256',
            new TextEncoder().encode(name.trim())
        );
        return bytesToHex(new Uint8Array(hash));
    }

    async function encryptAESGCM(plainText, keyHex) {
        const key = await crypto.subtle.importKey(
            'raw',
            hexToBytes(keyHex),
            { name: 'AES-GCM' },
            false,
            ['encrypt']
        );

        const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
        const data = new TextEncoder().encode(plainText);

        const encrypted = await crypto.subtle.encrypt(
            { name: 'AES-GCM', iv, tagLength: 128 },
            key,
            data
        );

        const encryptedArr = new Uint8Array(encrypted);
        const payload = new Uint8Array(iv.length + encryptedArr.length);

        payload.set(iv);
        payload.set(encryptedArr, iv.length);

        return bytesToBase64(payload);
    }

    async function decryptAESGCM(b64Payload, keyHex) {
        const data = base64ToBytes(b64Payload);

        if (data.length < IV_LEN + TAG_LEN) {
            throw new Error('Data too short');
        }

        const iv = data.slice(0, IV_LEN);
        const ciphertextWithTag = data.slice(IV_LEN);

        const key = await crypto.subtle.importKey(
            'raw',
            hexToBytes(keyHex),
            { name: 'AES-GCM' },
            false,
            ['decrypt']
        );

        const decrypted = await crypto.subtle.decrypt(
            { name: 'AES-GCM', iv, tagLength: 128 },
            key,
            ciphertextWithTag
        );

        return new TextDecoder().decode(decrypted);
    }

    async function encryptBinaryAESGCM(dataBytes, keyHex) {
        const key = await crypto.subtle.importKey(
            'raw',
            hexToBytes(keyHex),
            { name: 'AES-GCM' },
            false,
            ['encrypt']
        );

        const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
        const encrypted = await crypto.subtle.encrypt(
            { name: 'AES-GCM', iv, tagLength: 128 },
            key,
            dataBytes
        );

        return concatBytes([iv, new Uint8Array(encrypted)]);
    }

    async function decryptBinaryAESGCM(payloadBytes, keyHex) {
        if (payloadBytes.length < IV_LEN + TAG_LEN) {
            throw new Error('Media payload too short');
        }

        const key = await crypto.subtle.importKey(
            'raw',
            hexToBytes(keyHex),
            { name: 'AES-GCM' },
            false,
            ['decrypt']
        );

        const iv = payloadBytes.slice(0, IV_LEN);
        const ciphertextWithTag = payloadBytes.slice(IV_LEN);
        const decrypted = await crypto.subtle.decrypt(
            { name: 'AES-GCM', iv, tagLength: 128 },
            key,
            ciphertextWithTag
        );

        return new Uint8Array(decrypted);
    }

    function buildEncryptedMediaName(originalName) {
        const clean = String(originalName || 'media.bin').trim() || 'media.bin';
        return clean.endsWith(MEDIA_CONTAINER_EXT) ? clean : `${clean}${MEDIA_CONTAINER_EXT}`;
    }

    function isEncryptedMediaName(name) {
        return new RegExp(`${MEDIA_CONTAINER_EXT}(?:$|[?#])`, 'i').test(String(name || ''));
    }

    function isEncryptableMediaFile(file) {
        return Boolean(
            file &&
            typeof file.type === 'string' &&
            /^(image|audio|video)\//i.test(file.type)
        );
    }

    async function buildEncryptedMediaFile(file, keyHex, slotId) {
        const sourceBytes = new Uint8Array(await file.arrayBuffer());
        const encryptedPayload = await encryptBinaryAESGCM(sourceBytes, keyHex);
        const metadata = {
            version: 1,
            keyId: slotId,
            mime: file.type || 'application/octet-stream',
            originalName: file.name || 'media.bin',
            originalSize: file.size || sourceBytes.length
        };
        const metaBytes = utf8ToBytes(JSON.stringify(metadata));
        const header = concatBytes([
            utf8ToBytes(MEDIA_CONTAINER_MAGIC),
            uint32ToBytes(metaBytes.length),
            metaBytes
        ]);
        const containerBytes = concatBytes([header, encryptedPayload]);

        return new File(
            [containerBytes],
            buildEncryptedMediaName(file.name),
            {
                type: MEDIA_ENCRYPTED_MIME,
                lastModified: Date.now()
            }
        );
    }

    function parseEncryptedMediaContainer(bytes) {
        const magicBytes = utf8ToBytes(MEDIA_CONTAINER_MAGIC);

        if (bytes.length < magicBytes.length + 4 + IV_LEN + TAG_LEN) {
            throw new Error('Encrypted media container too short');
        }

        const actualMagic = bytesToUtf8(bytes.slice(0, magicBytes.length));
        if (actualMagic !== MEDIA_CONTAINER_MAGIC) {
            throw new Error('Unknown encrypted media format');
        }

        const metaLength = bytesToUint32(bytes, magicBytes.length);
        const metaStart = magicBytes.length + 4;
        const metaEnd = metaStart + metaLength;

        if (metaEnd > bytes.length) {
            throw new Error('Broken encrypted media metadata');
        }

        const metadata = JSON.parse(bytesToUtf8(bytes.slice(metaStart, metaEnd)));
        return {
            metadata,
            encryptedPayload: bytes.slice(metaEnd)
        };
    }

    function getAllKeys() {
        const all = {};

        if (DERIVED_KEYS) Object.assign(all, DERIVED_KEYS);
        if (CUSTOM_KEYS) {
            for (const [slot, info] of Object.entries(CUSTOM_KEYS)) {
                if (info && typeof info === 'object' && info.key) {
                    all[slot] = info.key;
                } else if (typeof info === 'string') {
                    all[slot] = info;
                }
            }
        }
        if (TEMP_KEY) all['@temp'] = TEMP_KEY;

        return all;
    }

    function getCustomKeyLabel(slot) {
        const info = CUSTOM_KEYS[slot];
        if (!info || typeof info !== 'object') return '';
        return info.label || '';
    }

    function getCurrentKeyHex() {
        return getAllKeys()[currentKeySlot] || null;
    }

    function hasAnyKeys() {
        return Boolean(DERIVED_KEYS || Object.keys(CUSTOM_KEYS).length || TEMP_KEY);
    }

    // ============================================================
    // Markerless Russian-word transport
    // ============================================================

    const WORDS_CODEC_ID = 1;
    const WORDS_PACKET_MAGIC = new Uint8Array([0x56, 0x4b, 0x57, 0x31]); // VKW1
    const WORDS_PACKET_HEADER_LEN = 32;
    const WORDS_GROUP_ID_LEN = 12;
    const WORDS_MAX_RAW_CHUNK = 1200;
    const WORD_FRAGMENT_GROUPS = new Map();
    const RU_WORDS_DICTIONARY_SET = new Set(RU_WORDS_DICTIONARY);
    let wordGroupsLoaded = false;

    function persistWordFragmentGroups() {
        try {
            const saved = Array.from(WORD_FRAGMENT_GROUPS.values())
                .filter(group => group.expiresAt > Date.now())
                .map(group => ({
                    key: group.key,
                    groupId: group.groupId,
                    partCount: group.partCount,
                    totalPlaintextLength: group.totalPlaintextLength,
                    compressed: group.compressed,
                    expiresAt: group.expiresAt,
                    parts: Array.from(group.parts.entries()).map(([index, part]) => ({
                        index,
                        payload: bytesToBase64(part.payload)
                    }))
                }));
            localStorage.setItem(WORDS_GROUP_STORAGE_KEY, JSON.stringify(saved));
        } catch {
            // Private browsing or disabled storage must not disable decryption.
        }
    }

    function loadWordFragmentGroups() {
        if (wordGroupsLoaded) return;
        wordGroupsLoaded = true;

        try {
            const saved = JSON.parse(localStorage.getItem(WORDS_GROUP_STORAGE_KEY) || '[]');
            saved.forEach(raw => {
                if (!raw || raw.expiresAt <= Date.now() || !raw.key) return;
                const group = {
                    ...raw,
                    parts: new Map(),
                    elements: new Map()
                };
                (raw.parts || []).forEach(part => {
                    if (Number.isInteger(part.index) && typeof part.payload === 'string') {
                        group.parts.set(part.index, {
                            partIndex: part.index,
                            payload: base64ToBytes(part.payload)
                        });
                    }
                });
                WORD_FRAGMENT_GROUPS.set(group.key, group);
            });
            persistWordFragmentGroups();
        } catch {
            localStorage.removeItem(WORDS_GROUP_STORAGE_KEY);
        }
    }

    function writeUint16(bytes, offset, value) {
        new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).setUint16(offset, value, false);
    }

    function readUint16(bytes, offset) {
        return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).getUint16(offset, false);
    }

    function isWordsDictionaryText(text) {
        const words = String(text || '').trim().split(/\s+/u);
        return words.length > 0 && words.every(word => RU_WORDS_DICTIONARY_SET.has(word));
    }

    function encodeBytesToWords(bytes, dictionary = RU_WORDS_DICTIONARY) {
        if (!Number.isInteger(bytes.length) || bytes.length > 0xffffffff) {
            throw new Error('Слишком большой словарный payload');
        }

        const source = concatBytes([uint32ToBytes(bytes.length), bytes]);
        const words = [];
        let accumulator = 0;
        let bitCount = 0;

        source.forEach(byte => {
            accumulator = (accumulator << 8) | byte;
            bitCount += 8;

            while (bitCount >= WORDS_BITS) {
                bitCount -= WORDS_BITS;
                words.push(dictionary[(accumulator >>> bitCount) & 0x1fff]);
                accumulator = bitCount ? accumulator & ((1 << bitCount) - 1) : 0;
            }
        });

        if (bitCount) {
            words.push(dictionary[(accumulator << (WORDS_BITS - bitCount)) & 0x1fff]);
        }

        return words.join(' ');
    }

    function decodeWordsToBytes(text, dictionary = RU_WORDS_DICTIONARY) {
        const words = String(text || '').trim().split(/\s+/u);
        if (!words.length || words.length > 10000) throw new Error('Недопустимое число слов');

        const indexes = words.map(word => dictionary.indexOf(word));
        if (indexes.some(index => index < 0)) throw new Error('Слово отсутствует в словаре');

        const output = [];
        let accumulator = 0;
        let bitCount = 0;

        indexes.forEach(index => {
            accumulator = (accumulator << WORDS_BITS) | index;
            bitCount += WORDS_BITS;

            while (bitCount >= 8) {
                bitCount -= 8;
                output.push((accumulator >>> bitCount) & 0xff);
                accumulator = bitCount ? accumulator & ((1 << bitCount) - 1) : 0;
            }
        });

        if (bitCount && accumulator !== 0) throw new Error('Ненулевые биты заполнения');
        if (output.length < 4) throw new Error('Словарный payload слишком короткий');

        const outputBytes = Uint8Array.from(output);
        const length = bytesToUint32(outputBytes, 0);
        const expectedLength = length + 4;
        if (outputBytes.length < expectedLength) throw new Error('Неверная длина словарного payload');
        if (outputBytes.slice(expectedLength).some(byte => byte !== 0)) {
            throw new Error('Ненулевые биты после словарного payload');
        }
        return outputBytes.slice(4, expectedLength);
    }

    async function compressTransportBytes(bytes) {
        if (typeof CompressionStream !== 'function') {
            return { bytes, compressed: false };
        }

        const stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'));
        const compressed = new Uint8Array(await new Response(stream).arrayBuffer());
        return compressed.length < bytes.length
            ? { bytes: compressed, compressed: true }
            : { bytes, compressed: false };
    }

    async function decompressTransportBytes(bytes) {
        if (typeof DecompressionStream !== 'function') {
            throw new Error('Эта платформа не умеет распаковывать gzip');
        }

        const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
        return new Uint8Array(await new Response(stream).arrayBuffer());
    }

    function buildWordsPacket(payload, metadata) {
        const packet = new Uint8Array(WORDS_PACKET_HEADER_LEN + payload.length);
        packet.set(WORDS_PACKET_MAGIC, 0);
        packet[4] = 1;
        packet[5] = metadata.compressed ? 1 : 0;
        packet[6] = WORDS_CODEC_ID;
        packet[7] = 1;
        packet.set(metadata.groupId, 8);
        writeUint16(packet, 20, metadata.partIndex);
        writeUint16(packet, 22, metadata.partCount);
        new DataView(packet.buffer).setUint32(24, metadata.totalPlaintextLength, false);
        new DataView(packet.buffer).setUint32(28, payload.length, false);
        packet.set(payload, WORDS_PACKET_HEADER_LEN);
        return packet;
    }

    function parseWordsPacket(packet) {
        if (packet.length < WORDS_PACKET_HEADER_LEN) throw new Error('Пакет слишком короткий');
        if (!WORDS_PACKET_MAGIC.every((value, index) => packet[index] === value)) {
            throw new Error('Неизвестная версия словарного пакета');
        }
        if (packet[4] !== 1 || packet[6] !== WORDS_CODEC_ID || packet[7] !== 1) {
            throw new Error('Несовместимый словарный пакет');
        }

        const payloadLength = bytesToUint32(packet, 28);
        if (payloadLength !== packet.length - WORDS_PACKET_HEADER_LEN) {
            throw new Error('Повреждённая длина словарного пакета');
        }

        return {
            compressed: Boolean(packet[5] & 1),
            groupId: bytesToHex(packet.slice(8, 20)),
            partIndex: readUint16(packet, 20),
            partCount: readUint16(packet, 22),
            totalPlaintextLength: bytesToUint32(packet, 24),
            payload: packet.slice(WORDS_PACKET_HEADER_LEN)
        };
    }

    function buildWordsPacketText(payload, metadata, keyHex) {
        return encryptBinaryAESGCM(buildWordsPacket(payload, metadata), keyHex)
            .then(encrypted => encodeBytesToWords(encrypted));
    }

    async function fitWordsChunk(payload, start, metadata, partCount, maxRawChunk) {
        const remaining = payload.length - start;
        const upper = Math.min(maxRawChunk, remaining);

        for (let size = upper; size > 0; size -= 1) {
            const candidate = payload.slice(start, start + size);
            const text = await buildWordsPacketText(candidate, {
                ...metadata,
                partIndex: 0,
                partCount
            }, metadata.keyHex);

            if (text.length <= MAX_VK_UTF16_UNITS) return size;
        }

        throw new Error('Даже минимальная часть не помещается в лимит VK');
    }

    async function encodePlaintextToWordMessages(plainText, keyHex) {
        const plainBytes = utf8ToBytes(plainText);
        const compressed = await compressTransportBytes(plainBytes);
        const groupId = crypto.getRandomValues(new Uint8Array(WORDS_GROUP_ID_LEN));
        const metadata = {
            compressed: compressed.compressed,
            groupId,
            totalPlaintextLength: plainBytes.length,
            keyHex
        };
        let maxRawChunk = WORDS_MAX_RAW_CHUNK;

        for (let attempt = 0; attempt < 32 && maxRawChunk > 0; attempt += 1) {
            let partCount = Math.max(1, Math.ceil(compressed.bytes.length / maxRawChunk));
            let chunks = [];

            for (let pass = 0; pass < 4; pass += 1) {
                chunks = [];
                let offset = 0;

                while (offset < compressed.bytes.length) {
                    const size = await fitWordsChunk(
                        compressed.bytes,
                        offset,
                        metadata,
                        partCount,
                        maxRawChunk
                    );
                    chunks.push(compressed.bytes.slice(offset, offset + size));
                    offset += size;
                }

                if (chunks.length === partCount) break;
                partCount = chunks.length;
            }

            const messages = await Promise.all(chunks.map((chunk, partIndex) => buildWordsPacketText(chunk, {
                ...metadata,
                partIndex,
                partCount: chunks.length
            }, keyHex)));

            if (messages.every(message => message.length <= MAX_VK_UTF16_UNITS)) {
                return messages;
            }

            // AES-GCM uses a fresh nonce for each attempt, so reserve margin
            // and validate the exact final strings before returning them.
            maxRawChunk -= 32;
        }

        throw new Error('Не удалось безопасно разбить словарное сообщение');
    }

    async function decryptWordMessage(text, keyHex) {
        if (!isWordsDictionaryText(text)) return null;

        const encrypted = decodeWordsToBytes(text);
        const packet = parseWordsPacket(await decryptBinaryAESGCM(encrypted, keyHex));
        if (!packet.partCount || packet.partIndex >= packet.partCount) {
            throw new Error('Неверная нумерация частей');
        }

        return packet;
    }

    async function completeWordGroup(group) {
        const ordered = [];
        for (let index = 0; index < group.partCount; index += 1) {
            const part = group.parts.get(index);
            if (!part) return null;
            ordered.push(part.payload);
        }

        const payload = concatBytes(ordered);
        const plainBytes = group.compressed
            ? await decompressTransportBytes(payload)
            : payload;

        if (plainBytes.length !== group.totalPlaintextLength) {
            throw new Error('Неверная длина исходного текста');
        }

        WORD_FRAGMENT_GROUPS.delete(group.key);
        persistWordFragmentGroups();
        return bytesToUtf8(plainBytes);
    }

    async function acceptWordFragment(packet, msgEl, originalText) {
        loadWordFragmentGroups();
        const key = `${currentChatContextId}:${packet.groupId}`;
        let group = WORD_FRAGMENT_GROUPS.get(key);

        if (!group || group.partCount !== packet.partCount || group.totalPlaintextLength !== packet.totalPlaintextLength) {
            group = {
                key,
                groupId: packet.groupId,
                partCount: packet.partCount,
                totalPlaintextLength: packet.totalPlaintextLength,
                compressed: packet.compressed,
                parts: new Map(),
                elements: new Map(),
                expiresAt: Date.now() + WORDS_GROUP_TTL_MS
            };
            WORD_FRAGMENT_GROUPS.set(key, group);
        }

        if (group.expiresAt < Date.now()) {
            WORD_FRAGMENT_GROUPS.delete(key);
            return null;
        }

        group.parts.set(packet.partIndex, packet);
        group.elements.set(packet.partIndex, msgEl);
        persistWordFragmentGroups();

        if (group.partCount > 1 && group.parts.size < group.partCount) {
            createFragmentStatusInterface(msgEl, group.parts.size, group.partCount, originalText);
            return null;
        }

        const decryptedText = await completeWordGroup(group);
        if (decryptedText === null) return null;

        const first = group.elements.get(0) || msgEl;
        createToggleInterface(originalText, decryptedText, first);
        group.elements.forEach((element, index) => {
            if (index !== 0) {
                element.textContent = '';
                element.dataset.vkdecDone = 'true';
                element.hidden = true;
            }
        });
        return decryptedText;
    }
